{
  "name": "gravity-grand-prix",
  "version": "1.0.0",
  "private": true,
  "type": "module",
  "description": "A 3D anti-gravity kart racer",
  "scripts": {
    "dev": "vite --host 0.0.0.0 --port 3002",
    "build": "vite build --base ./",
    "preview": "vite preview --host 0.0.0.0 --port 3002"
  },
  "dependencies": {
    "three": "^0.180.0"
  },
  "devDependencies": {
    "vite": "^7.1.5"
  }
}

:root {
  --ink: #0b0718;
  --deep: #140d2e;
  --violet: #6d3cff;
  --magenta: #ff2d7e;
  --pink: #ff6fb5;
  --cyan: #54f7ff;
  --mint: #a8ffde;
  --gold: #ffd166;
  --cream: #fff4df;
  --glass: rgba(15, 9, 38, 0.58);
  --line: rgba(255, 255, 255, 0.15);
  --display: "Arial Black", "Helvetica Neue", "Segoe UI", sans-serif;
  --body: "Trebuchet MS", "Segoe UI", system-ui, sans-serif;
}

* {
  box-sizing: border-box;
  -webkit-tap-highlight-color: transparent;
}

html,
body {
  margin: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: #0b0718;
  color: var(--cream);
  font-family: var(--body);
  user-select: none;
}

#app {
  position: fixed;
  inset: 0;
  overflow: hidden;
  background: radial-gradient(circle at 50% 20%, #38247b 0%, #0b0718 70%);
}

#game {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  touch-action: none;
}

.screen-vignette {
  pointer-events: none;
  position: absolute;
  inset: 0;
  z-index: 2;
  background:
    radial-gradient(circle at 50% 45%, transparent 38%, rgba(7, 4, 18, 0.34) 100%),
    linear-gradient(to bottom, rgba(7, 4, 18, 0.15), transparent 25%, transparent 72%, rgba(7, 4, 18, 0.4));
}

.screen-vignette::after {
  content: "";
  position: absolute;
  inset: 0;
  opacity: 0.045;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 140 140' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.8'/%3E%3C/svg%3E");
  mix-blend-mode: screen;
}

#boost-fx {
  pointer-events: none;
  position: absolute;
  inset: 0;
  z-index: 3;
  opacity: 0;
  background:
    radial-gradient(ellipse at center, transparent 34%, rgba(84, 247, 255, 0.2) 76%, rgba(255, 45, 126, 0.2) 100%),
    repeating-conic-gradient(from 0deg at 50% 50%, transparent 0deg 5deg, rgba(255, 255, 255, 0.1) 5.3deg 5.6deg, transparent 6deg 11deg);
  transition: opacity 0.15s ease;
  mix-blend-mode: screen;
}

#boost-fx.on {
  opacity: 1;
  animation: speedPulse 0.45s linear infinite;
}

#flash {
  pointer-events: none;
  position: absolute;
  inset: 0;
  z-index: 12;
  background: #fff;
  opacity: 0;
}

#flash.fire {
  animation: flash 0.45s ease-out;
}

@keyframes flash {
  0% { opacity: 0.65; }
  100% { opacity: 0; }
}

@keyframes speedPulse {
  0% { transform: scale(1); }
  50% { transform: scale(1.035); }
  100% { transform: scale(1); }
}

.hidden {
  opacity: 0 !important;
  pointer-events: none !important;
}

/* ============================ HUD ============================ */

#hud {
  position: absolute;
  inset: 0;
  z-index: 5;
  pointer-events: none;
  transition: opacity 0.4s ease;
}

.hud-top {
  position: absolute;
  inset: 0 0 auto 0;
  display: grid;
  grid-template-columns: minmax(150px, 1fr) auto minmax(150px, 1fr);
  align-items: start;
  padding: max(18px, env(safe-area-inset-top)) max(22px, env(safe-area-inset-right)) 0 max(22px, env(safe-area-inset-left));
  gap: 18px;
}

.hud-card {
  position: relative;
  width: fit-content;
  min-width: 168px;
  padding: 12px 16px 13px;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: linear-gradient(145deg, rgba(25, 15, 58, 0.78), rgba(10, 7, 25, 0.5));
  box-shadow: 0 18px 44px rgba(0, 0, 0, 0.28), inset 0 1px 0 rgba(255, 255, 255, 0.1);
  backdrop-filter: blur(14px) saturate(1.25);
}

.hud-card::before {
  content: "";
  position: absolute;
  left: 16px;
  right: 16px;
  top: 0;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(84, 247, 255, 0.8), transparent);
}

.eyebrow {
  display: block;
  font-family: var(--display);
  font-size: 9px;
  letter-spacing: 0.2em;
  font-weight: 900;
  color: rgba(255, 244, 223, 0.55);
}

.position-line {
  display: flex;
  align-items: baseline;
  margin-top: 1px;
  line-height: 0.95;
}

#position {
  font-family: var(--display);
  font-weight: 900;
  font-size: clamp(42px, 5.2vw, 64px);
  letter-spacing: -0.06em;
  color: var(--cream);
  text-shadow: 0 0 24px rgba(84, 247, 255, 0.22);
}

.suffix {
  font-family: var(--display);
  font-size: clamp(15px, 1.6vw, 21px);
  font-weight: 900;
  margin-left: 3px;
  color: var(--cyan);
}

.of {
  font-family: var(--display);
  font-size: 13px;
  margin-left: 6px;
  color: rgba(255, 244, 223, 0.42);
}

.lap-line {
  margin-top: 5px;
  font-family: var(--display);
  font-size: 12px;
  font-weight: 900;
  letter-spacing: 0.13em;
  color: rgba(255, 244, 223, 0.6);
}

.lap-line strong {
  color: var(--cream);
  font-size: 17px;
  margin: 0 2px;
}

.lap-line span {
  color: rgba(255, 244, 223, 0.35);
}

.race-clock {
  justify-self: center;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 3px;
  padding-top: 3px;
  text-shadow: 0 2px 20px rgba(0, 0, 0, 0.65);
}

.race-clock .eyebrow {
  color: rgba(255, 244, 223, 0.5);
}

#race-time {
  font-family: var(--display);
  font-size: clamp(20px, 2.3vw, 30px);
  font-weight: 900;
  letter-spacing: 0.06em;
  font-variant-numeric: tabular-nums;
  color: var(--cream);
}

.map-card {
  justify-self: end;
  width: 184px;
  padding: 10px 11px 11px;
}

.map-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 3px;
}

.live-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--magenta);
  box-shadow: 0 0 10px var(--magenta);
  animation: blink 1.3s ease infinite;
}

@keyframes blink {
  50% { opacity: 0.3; }
}

#minimap {
  display: block;
  width: 160px;
  height: 160px;
}

.gravity-chip {
  position: absolute;
  top: max(94px, calc(env(safe-area-inset-top) + 84px));
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 7px 13px 7px 10px;
  border: 1px solid rgba(84, 247, 255, 0.26);
  border-radius: 999px;
  background: rgba(10, 8, 28, 0.58);
  box-shadow: 0 0 24px rgba(84, 247, 255, 0.08), inset 0 1px 0 rgba(255, 255, 255, 0.1);
  backdrop-filter: blur(10px);
  font-family: var(--display);
  font-size: 9px;
  letter-spacing: 0.16em;
  color: rgba(168, 255, 222, 0.85);
  transition: all 0.3s ease;
}

.gravity-icon {
  display: grid;
  place-items: center;
  width: 18px;
  height: 18px;
  border-radius: 50%;
  background: rgba(84, 247, 255, 0.12);
  color: var(--cyan);
  font-size: 9px;
  line-height: 1;
  transform: rotate(180deg);
  transition: transform 0.45s cubic-bezier(0.3, 1.5, 0.5, 1);
}

.gravity-bars {
  display: flex;
  gap: 2px;
  align-items: flex-end;
  height: 12px;
}

.gravity-bars i {
  width: 2px;
  border-radius: 2px;
  background: var(--cyan);
  opacity: 0.55;
  animation: meter 1.1s ease-in-out infinite;
}

.gravity-bars i:nth-child(1) { height: 5px; animation-delay: 0s; }
.gravity-bars i:nth-child(2) { height: 8px; animation-delay: 0.12s; }
.gravity-bars i:nth-child(3) { height: 11px; animation-delay: 0.24s; }

@keyframes meter {
  50% { opacity: 1; transform: scaleY(1.2); }
}

.gravity-chip.flip {
  border-color: rgba(255, 45, 126, 0.7);
  color: #fff;
  background: linear-gradient(90deg, rgba(255, 45, 126, 0.35), rgba(109, 60, 255, 0.38));
  box-shadow: 0 0 34px rgba(255, 45, 126, 0.45), inset 0 0 20px rgba(255, 45, 126, 0.18);
  animation: chipPulse 0.75s ease-in-out infinite;
}

.gravity-chip.flip .gravity-icon {
  transform: rotate(0deg);
  color: #fff;
  background: rgba(255, 255, 255, 0.2);
}

.gravity-chip.flip .gravity-bars i {
  background: var(--pink);
  opacity: 1;
}

@keyframes chipPulse {
  50% { box-shadow: 0 0 48px rgba(255, 45, 126, 0.65), inset 0 0 24px rgba(255, 45, 126, 0.3); }
}

.banner {
  position: absolute;
  top: 31%;
  left: 50%;
  transform: translate(-50%, -50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
  width: min(700px, 90vw);
  text-align: center;
  opacity: 0;
  pointer-events: none;
}

.banner.show {
  animation: bannerIn 2.2s cubic-bezier(0.2, 0.9, 0.3, 1) forwards;
}

.banner strong {
  font-family: var(--display);
  font-size: clamp(38px, 6vw, 74px);
  font-weight: 900;
  font-style: italic;
  letter-spacing: -0.045em;
  line-height: 0.95;
  color: var(--cream);
  text-shadow: 0 0 30px rgba(84, 247, 255, 0.45), 0 6px 0 rgba(26, 10, 58, 0.4);
  -webkit-text-stroke: 1px rgba(255, 255, 255, 0.2);
}

.banner .kicker {
  font-family: var(--display);
  font-size: 10px;
  letter-spacing: 0.3em;
  color: var(--cyan);
}

#banner-kicker {
  font-family: var(--display);
  font-size: 10px;
  letter-spacing: 0.3em;
  color: var(--cyan);
}

#banner-sub {
  font-family: var(--display);
  font-size: 10px;
  letter-spacing: 0.22em;
  color: rgba(255, 244, 223, 0.65);
}

.banner.magenta strong { color: #fff; text-shadow: 0 0 34px rgba(255, 45, 126, 0.8), 0 6px 0 rgba(60, 10, 40, 0.5); }
.banner.gold strong { color: var(--gold); text-shadow: 0 0 34px rgba(255, 209, 102, 0.65), 0 6px 0 rgba(60, 36, 8, 0.45); }

@keyframes bannerIn {
  0% { opacity: 0; transform: translate(-50%, -50%) scale(0.82); filter: blur(8px); }
  12% { opacity: 1; transform: translate(-50%, -50%) scale(1.03); filter: blur(0); }
  20% { transform: translate(-50%, -50%) scale(1); }
  76% { opacity: 1; }
  100% { opacity: 0; transform: translate(-50%, -56%) scale(1.02); }
}

.countdown {
  position: absolute;
  top: 48%;
  left: 50%;
  transform: translate(-50%, -50%);
  font-family: var(--display);
  font-size: clamp(110px, 19vw, 250px);
  font-weight: 900;
  font-style: italic;
  line-height: 0.8;
  color: var(--cream);
  text-shadow: 0 0 50px rgba(84, 247, 255, 0.55), 0 10px 0 rgba(22, 9, 51, 0.35);
  -webkit-text-stroke: 2px rgba(255, 255, 255, 0.22);
  opacity: 0;
  pointer-events: none;
}

.countdown.pop {
  animation: countPop 0.9s cubic-bezier(0.16, 1.1, 0.3, 1) forwards;
}

.countdown.go {
  color: var(--mint);
  text-shadow: 0 0 60px rgba(84, 247, 255, 0.8), 0 0 120px rgba(255, 45, 126, 0.3), 0 10px 0 rgba(22, 9, 51, 0.35);
}

@keyframes countPop {
  0% { opacity: 0; transform: translate(-50%, -50%) scale(1.7); filter: blur(10px); }
  22% { opacity: 1; transform: translate(-50%, -50%) scale(0.96); filter: blur(0); }
  35% { transform: translate(-50%, -50%) scale(1); }
  72% { opacity: 1; }
  100% { opacity: 0; transform: translate(-50%, -50%) scale(0.78); }
}

.hud-bottom {
  position: absolute;
  inset: auto 0 0 0;
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  padding: 0 max(22px, env(safe-area-inset-right)) max(22px, env(safe-area-inset-bottom)) max(22px, env(safe-area-inset-left));
}

.bottom-left,
.bottom-right {
  display: flex;
  align-items: flex-end;
  gap: 14px;
}

.item-slot {
  position: relative;
  width: 94px;
  padding: 10px 10px 8px;
  border: 1px solid rgba(255, 255, 255, 0.18);
  border-radius: 20px;
  background: linear-gradient(150deg, rgba(33, 19, 70, 0.82), rgba(11, 7, 28, 0.58));
  box-shadow: 0 18px 45px rgba(0, 0, 0, 0.3), inset 0 1px 0 rgba(255, 255, 255, 0.1);
  backdrop-filter: blur(14px);
  text-align: center;
  transition: border-color 0.3s ease, box-shadow 0.3s ease;
}

.item-slot.filled {
  border-color: rgba(255, 209, 102, 0.7);
  box-shadow: 0 0 30px rgba(255, 209, 102, 0.18), 0 18px 45px rgba(0, 0, 0, 0.3), inset 0 1px 0 rgba(255, 255, 255, 0.16);
}

.item-slot.rolling .item-orb {
  animation: rollItem 0.18s linear infinite;
}

.item-slot.empty .item-orb {
  opacity: 0.38;
  filter: grayscale(1);
}

.item-label {
  font-family: var(--display);
  font-size: 8px;
  letter-spacing: 0.22em;
  color: rgba(255, 244, 223, 0.48);
  margin-bottom: 5px;
}

.item-orb {
  width: 54px;
  height: 54px;
  margin: 0 auto;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: radial-gradient(circle at 36% 30%, #fff8d9, #ffd166 38%, #ff7a45 70%, #5b1a42 100%);
  box-shadow: 0 0 22px rgba(255, 209, 102, 0.55), inset 0 -5px 12px rgba(90, 20, 60, 0.35);
  color: #32102d;
  font-size: 26px;
  font-weight: 900;
  transition: transform 0.2s ease;
}

.item-slot.filled:hover .item-orb {
  transform: scale(1.06);
}

.item-name {
  margin-top: 5px;
  font-family: var(--display);
  font-size: 8px;
  font-weight: 900;
  letter-spacing: 0.1em;
  color: rgba(255, 244, 223, 0.78);
}

@keyframes rollItem {
  0% { transform: rotateY(0deg) scale(0.92); }
  50% { transform: rotateY(90deg) scale(1.08); }
  100% { transform: rotateY(180deg) scale(0.92); }
}

.coin-pill {
  display: flex;
  align-items: baseline;
  gap: 3px;
  padding: 8px 12px;
  margin-bottom: 8px;
  border: 1px solid rgba(255, 209, 102, 0.22);
  border-radius: 999px;
  background: rgba(15, 10, 36, 0.55);
  backdrop-filter: blur(10px);
  font-family: var(--display);
  font-weight: 900;
  font-size: 16px;
  color: var(--gold);
  text-shadow: 0 0 12px rgba(255, 209, 102, 0.4);
}

.coin-glyph {
  font-size: 12px;
  transform: translateY(-1px);
}

.coin-max {
  font-size: 9px;
  color: rgba(255, 244, 223, 0.38);
}

.drift-wrap {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 7px;
  padding-bottom: 11px;
}

.drift-label {
  font-family: var(--display);
  font-size: 8px;
  letter-spacing: 0.22em;
  color: rgba(255, 244, 223, 0.45);
}

.drift-bars {
  display: flex;
  gap: 4px;
}

.drift-bars i {
  width: 26px;
  height: 7px;
  border-radius: 3px;
  background: rgba(255, 255, 255, 0.12);
  border: 1px solid rgba(255, 255, 255, 0.1);
  transition: all 0.12s ease;
}

.drift-bars i.on:nth-child(1) { background: var(--cyan); box-shadow: 0 0 12px var(--cyan); }
.drift-bars i.on:nth-child(2) { background: var(--gold); box-shadow: 0 0 12px var(--gold); }
.drift-bars i.on:nth-child(3) { background: var(--magenta); box-shadow: 0 0 12px var(--magenta); }

.speedo {
  --speed: 0;
  position: relative;
  width: 122px;
  height: 122px;
  border-radius: 50%;
  background: conic-gradient(from 220deg, var(--cyan) 0deg, var(--cyan) calc(var(--speed) * 2.8deg), rgba(255, 255, 255, 0.1) calc(var(--speed) * 2.8deg), rgba(255, 255, 255, 0.1) 280deg, transparent 280deg);
  box-shadow: 0 0 30px rgba(84, 247, 255, 0.12), 0 18px 45px rgba(0, 0, 0, 0.3);
  padding: 5px;
}

.speedo::before {
  content: "";
  position: absolute;
  inset: 5px;
  border-radius: 50%;
  background: radial-gradient(circle at 50% 40%, #211446, #0d0822 72%);
  border: 1px solid rgba(255, 255, 255, 0.1);
}

.speedo-inner {
  position: absolute;
  inset: 5px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  z-index: 1;
}

#speed-value {
  font-family: var(--display);
  font-size: 34px;
  font-weight: 900;
  line-height: 0.9;
  letter-spacing: -0.05em;
  font-variant-numeric: tabular-nums;
  color: var(--cream);
}

.speedo-inner small {
  font-family: var(--display);
  font-size: 7px;
  letter-spacing: 0.18em;
  color: rgba(255, 244, 223, 0.48);
  margin-top: 4px;
}

.touch-controls {
  display: none;
}

.icon-btn {
  pointer-events: auto;
  position: absolute;
  z-index: 30;
  display: grid;
  place-items: center;
  width: 38px;
  height: 38px;
  border: 1px solid rgba(255, 255, 255, 0.18);
  border-radius: 50%;
  background: rgba(15, 9, 38, 0.55);
  color: var(--cream);
  font-family: var(--display);
  font-size: 13px;
  cursor: pointer;
  backdrop-filter: blur(10px);
  transition: background 0.2s ease, transform 0.2s ease;
}

.icon-btn:hover {
  background: rgba(60, 35, 110, 0.75);
  transform: scale(1.05);
}

.sound-btn {
  top: max(18px, env(safe-area-inset-top));
  right: max(22px, env(safe-area-inset-right));
}

.sound-btn.muted {
  color: rgba(255, 244, 223, 0.35);
}

.pause-btn {
  top: max(18px, env(safe-area-inset-top));
  right: max(70px, calc(env(safe-area-inset-right) + 48px));
  font-size: 10px;
  letter-spacing: 1px;
}

/* ============================ MENU ============================ */

.menu {
  position: absolute;
  inset: 0;
  z-index: 20;
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: clamp(24px, 5vw, 72px);
  background:
    linear-gradient(90deg, rgba(8, 5, 22, 0.86) 0%, rgba(8, 5, 22, 0.5) 38%, transparent 68%),
    linear-gradient(0deg, rgba(8, 5, 22, 0.62) 0%, transparent 35%);
  transition: opacity 0.6s ease, transform 0.6s ease;
}

.menu::before {
  content: "";
  position: absolute;
  inset: 0;
  background:
    radial-gradient(circle at 16% 46%, rgba(109, 60, 255, 0.26), transparent 32%),
    radial-gradient(circle at 72% 28%, rgba(255, 45, 126, 0.12), transparent 30%);
  pointer-events: none;
