    this.group.name = 'orbital-track';
    this.scene.add(this.group);

    const points = CONTROL_POINTS.map((p) => new THREE.Vector3(...p));
    this.curve = new THREE.CatmullRomCurve3(points, true, 'centripetal', 0.5);
    this.length = this.curve.getLength();
    this.samples = 1800;
    this.frames = [];
    this._buildFrames();
    this._buildTrackMesh();
    this._buildStartGate();
    this._buildGravityRings();
    this._buildBoostPads();
    this._buildMapPoints();
    this._buildDecorations();
  }

  rollAt(u) {
    const uu = wrap(u);
    const first = smootherstep(0.29, 0.43, uu);
    const second = smootherstep(0.6, 0.74, uu);
    return TAU * (first - second);
  }

  gravityAmount(u) {
    const uu = wrap(u);
    const a = 1 - Math.abs(clamp((uu - 0.36) / 0.09, -1, 1));
    const b = 1 - Math.abs(clamp((uu - 0.67) / 0.09, -1, 1));
    return clamp(Math.max(a, b), 0, 1);
  }

  inGravityZone(u) {
    const uu = wrap(u);
    return (uu > 0.285 && uu < 0.445) || (uu > 0.595 && uu < 0.75);
  }

  _buildFrames() {
    const n = this.samples;
    for (let i = 0; i < n; i++) {
      const u = i / n;
      const pos = this.curve.getPointAt(u);
      const tangent = this.curve.getTangentAt(u).normalize();
      let baseRight = new THREE.Vector3().crossVectors(tangent, UP);
      if (baseRight.lengthSq() < 0.0001) baseRight.set(1, 0, 0);
      baseRight.normalize();
      const baseUp = new THREE.Vector3().crossVectors(baseRight, tangent).normalize();

      const roll = this.rollAt(u);
      const c = Math.cos(roll);
      const s = Math.sin(roll);
      const right = baseRight.clone().multiplyScalar(c).addScaledVector(baseUp, s).normalize();
      const up = baseUp.clone().multiplyScalar(c).addScaledVector(baseRight, -s).normalize();
      const quat = quaternionFromFrame(right, up, tangent);

      this.frames.push({ u, pos, tangent, right, up, roll, quat });
    }
  }

  getFrame(u, out = {}) {
    const uu = wrap(u);
    const f = uu * this.samples;
    const i0 = Math.floor(f) % this.samples;
    const i1 = (i0 + 1) % this.samples;
    const t = f - Math.floor(f);
    const a = this.frames[i0];
    const b = this.frames[i1];

    const pos = out.pos || new THREE.Vector3();
    const tangent = out.tangent || new THREE.Vector3();
    const right = out.right || new THREE.Vector3();
    const up = out.up || new THREE.Vector3();

    pos.lerpVectors(a.pos, b.pos, t);
    tangent.lerpVectors(a.tangent, b.tangent, t).normalize();
    up.lerpVectors(a.up, b.up, t).normalize();
    right.crossVectors(tangent, up).normalize();
    up.crossVectors(right, tangent).normalize();

    out.pos = pos;
    out.tangent = tangent;
    out.right = right;
    out.up = up;
    out.u = uu;
    out.roll = this.rollAt(uu);
    out.quat = quaternionFromFrame(right, up, tangent);
    return out;
  }

  pointAt(u, lateral = 0, height = 0) {
    const f = this.getFrame(u);
    return f.pos.clone().addScaledVector(f.right, lateral).addScaledVector(f.up, height);
  }

  _buildTrackMesh() {
    const roadTexture = makeCanvasTexture(
      256,
      512,
      (ctx, w, h) => {
        ctx.fillStyle = '#241c48';
        ctx.fillRect(0, 0, w, h);
        const rng = (x) => {
          const v = Math.sin(x * 127.1) * 43758.5453;
          return v - Math.floor(v);
        };
        for (let i = 0; i < 1400; i++) {
          const x = rng(i * 2.17) * w;
          const y = rng(i * 3.31 + 9) * h;
          const a = 0.02 + rng(i * 5.7) * 0.08;
          ctx.fillStyle = rng(i * 7.1) > 0.5 ? `rgba(150,130,255,${a})` : `rgba(255,255,255,${a * 0.5})`;
          const r = 0.4 + rng(i * 1.9) * 1.6;
          ctx.fillRect(x, y, r, r);
        }
        const grad = ctx.createLinearGradient(0, 0, w, 0);
        grad.addColorStop(0, 'rgba(84,247,255,.08)');
        grad.addColorStop(0.5, 'rgba(255,45,126,.035)');
        grad.addColorStop(1, 'rgba(84,247,255,.08)');
        ctx.fillStyle = grad;
        ctx.fillRect(0, 0, w, h);
      },
      { wrapS: THREE.RepeatWrapping, wrapT: THREE.RepeatWrapping, repeat: [1, 90] }
    );

    const roadMat = new THREE.MeshStandardMaterial({
      map: roadTexture,
      color: 0x7b70c9,
      roughness: 0.78,
      metalness: 0.24,
      emissive: 0x0a0620,
      emissiveIntensity: 0.4,
    });

    const edgeL = new THREE.MeshStandardMaterial({
      color: 0x3a0b3c,
      emissive: 0xff2d7e,
      emissiveIntensity: 2.4,
      roughness: 0.35,
      metalness: 0.4,
    });
    const edgeR = new THREE.MeshStandardMaterial({
      color: 0x0b3340,
      emissive: 0x54f7ff,
      emissiveIntensity: 2.4,
      roughness: 0.35,
      metalness: 0.4,
    });
    const railMat = new THREE.MeshStandardMaterial({
      color: 0x191133,
      roughness: 0.55,
      metalness: 0.65,
      side: THREE.DoubleSide,
    });
    const underMat = new THREE.MeshStandardMaterial({
      color: 0x120c29,
      roughness: 0.75,
      metalness: 0.3,
      side: THREE.DoubleSide,
    });
    const glowL = new THREE.MeshBasicMaterial({ color: 0xff4f9a, toneMapped: false });
    const glowR = new THREE.MeshBasicMaterial({ color: 0x67fbff, toneMapped: false });

    const road = new THREE.Mesh(this._ribbon(-this.roadHalf, this.roadHalf, 0, 1), roadMat);
    road.receiveShadow = true;
    this.group.add(road);

    const leftEdge = new THREE.Mesh(this._ribbon(-this.edgeHalf, -this.roadHalf, 0.015, 0.02), edgeL);
    const rightEdge = new THREE.Mesh(this._ribbon(this.roadHalf, this.edgeHalf, 0.015, 0.02), edgeR);
    this.group.add(leftEdge, rightEdge);

    this.group.add(new THREE.Mesh(this._vertical(-this.edgeHalf, 0, 1.18, -1), railMat));
    this.group.add(new THREE.Mesh(this._vertical(this.edgeHalf, 0, 1.18, 1), railMat));
    this.group.add(new THREE.Mesh(this._vertical(-this.edgeHalf, 0, -1.35, -1), underMat));
    this.group.add(new THREE.Mesh(this._vertical(this.edgeHalf, 0, -1.35, 1), underMat));
    this.group.add(new THREE.Mesh(this._ribbon(-this.edgeHalf, this.edgeHalf, -1.36, 1, -1), underMat));

    this.group.add(new THREE.Mesh(this._ribbon(-this.edgeHalf - 0.02, -this.edgeHalf + 0.2, 1.19, 0.02), glowL));
    this.group.add(new THREE.Mesh(this._ribbon(this.edgeHalf - 0.2, this.edgeHalf + 0.02, 1.19, 0.02), glowR));
    this.group.add(new THREE.Mesh(this._ribbon(-this.edgeHalf - 0.02, -this.edgeHalf + 0.22, -1.36, 0.02, -1), glowL));
    this.group.add(new THREE.Mesh(this._ribbon(this.edgeHalf - 0.22, this.edgeHalf + 0.02, -1.36, 0.02, -1), glowR));

    // Dashed center line.
    const dashVerts = [];
    const dashNormals = [];
    const dashUvs = [];
    const dashIndices = [];
    const dashCount = 110;
    for (let i = 0; i < dashCount; i++) {
      const u0 = i / dashCount;
      const u1 = u0 + 0.0042;
      const fa = this.getFrame(u0);
      const fb = this.getFrame(u1);
      const base = dashVerts.length / 3;
      for (const [f, side] of [
        [fa, -0.16],
        [fa, 0.16],
        [fb, 0.16],
        [fb, -0.16],
      ]) {
        const p = f.pos.clone().addScaledVector(f.right, side).addScaledVector(f.up, 0.026);
        dashVerts.push(p.x, p.y, p.z);
        dashNormals.push(f.up.x, f.up.y, f.up.z);
        dashUvs.push(side > 0 ? 1 : 0, i / dashCount);
      }
      dashIndices.push(base, base + 1, base + 2, base, base + 2, base + 3);
    }
    const dashGeo = new THREE.BufferGeometry();
    dashGeo.setAttribute('position', new THREE.Float32BufferAttribute(dashVerts, 3));
    dashGeo.setAttribute('normal', new THREE.Float32BufferAttribute(dashNormals, 3));
    dashGeo.setAttribute('uv', new THREE.Float32BufferAttribute(dashUvs, 2));
    dashGeo.setIndex(dashIndices);
    const dashMat = new THREE.MeshBasicMaterial({
      color: 0xfff2d8,
      transparent: true,
      opacity: 0.55,
      toneMapped: false,
      side: THREE.DoubleSide,
    });
    this.group.add(new THREE.Mesh(dashGeo, dashMat));

    // Start / finish checker plate.
    const checkerTex = makeCanvasTexture(512, 128, (ctx, w, h) => {
      const cols = 16;
      const rows = 4;
      for (let y = 0; y < rows; y++) {
        for (let x = 0; x < cols; x++) {
          ctx.fillStyle = (x + y) % 2 ? '#f9f1dc' : '#171128';
          ctx.fillRect((x * w) / cols, (y * h) / rows, w / cols + 1, h / rows + 1);
        }
      }
    });
    const lineFrame = this.getFrame(0);
    const lineGroup = new THREE.Group();
    lineGroup.position.copy(lineFrame.pos).addScaledVector(lineFrame.up, 0.045);
    lineGroup.quaternion.copy(lineFrame.quat);
    const lineMesh = new THREE.Mesh(
      new THREE.PlaneGeometry(this.width - 0.3, 3.4).rotateX(-Math.PI / 2),
      new THREE.MeshBasicMaterial({ map: checkerTex, toneMapped: false })
    );
    lineGroup.add(lineMesh);
    this.group.add(lineGroup);
  }

  _ribbon(latA, latB, yOffset, uvRepeat = 1, normalSign = 1) {
    const n = this.samples;
    const positions = [];
    const normals = [];
    const uvs = [];
    const indices = [];
    for (let i = 0; i <= n; i++) {
      const f = this.frames[i % n];
      for (const lat of [latA, latB]) {
        const p = f.pos.clone().addScaledVector(f.right, lat).addScaledVector(f.up, yOffset);
        positions.push(p.x, p.y, p.z);
        normals.push(f.up.x * normalSign, f.up.y * normalSign, f.up.z * normalSign);
        uvs.push(lat === latA ? 0 : 1, (i / n) * uvRepeat);
      }
    }
    for (let i = 0; i < n; i++) {
      const a = i * 2;
      indices.push(a, a + 1, a + 3, a, a + 3, a + 2);
    }
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
    geo.setAttribute('normal', new THREE.Float32BufferAttribute(normals, 3));
    geo.setAttribute('uv', new THREE.Float32BufferAttribute(uvs, 2));
    geo.setIndex(indices);
    geo.computeBoundingSphere();
    return geo;
  }

  _vertical(lat, yA, yB, normalSign) {
    const n = this.samples;
    const positions = [];
    const normals = [];
    const uvs = [];
    const indices = [];
    for (let i = 0; i <= n; i++) {
      const f = this.frames[i % n];
      for (const y of [yA, yB]) {
        const p = f.pos.clone().addScaledVector(f.right, lat).addScaledVector(f.up, y);
        positions.push(p.x, p.y, p.z);
        normals.push(f.right.x * normalSign, f.right.y * normalSign, f.right.z * normalSign);
        uvs.push(0, (i / n) * 40);
      }
    }
    for (let i = 0; i < n; i++) {
      const a = i * 2;
      indices.push(a, a + 1, a + 3, a, a + 3, a + 2);
    }
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
    geo.setAttribute('normal', new THREE.Float32BufferAttribute(normals, 3));
    geo.setAttribute('uv', new THREE.Float32BufferAttribute(uvs, 2));
    geo.setIndex(indices);
    geo.computeBoundingSphere();
    return geo;
  }

  _buildStartGate() {
    const f = this.getFrame(0);
    const gate = new THREE.Group();
    gate.position.copy(f.pos);
    gate.quaternion.copy(f.quat);
    gate.position.addScaledVector(f.up, 0.05);

    const dark = new THREE.MeshStandardMaterial({ color: 0x1a1138, roughness: 0.45, metalness: 0.6 });
    const light = new THREE.MeshStandardMaterial({
      color: 0x2a1558,
      emissive: 0x6d3cff,
      emissiveIntensity: 1.6,
      roughness: 0.3,
      metalness: 0.5,
    });
    const cyan = new THREE.MeshBasicMaterial({ color: 0x54f7ff, toneMapped: false });
    const pink = new THREE.MeshBasicMaterial({ color: 0xff2d7e, toneMapped: false });

    for (const side of [-1, 1]) {
      const pillar = new THREE.Group();
      pillar.position.set(side * 11.8, 0, 0);
      const body = new THREE.Mesh(new THREE.CylinderGeometry(0.65, 0.9, 12, 8), dark);
      body.position.y = 6;
      pillar.add(body);
      const trim = new THREE.Mesh(new THREE.CylinderGeometry(0.71, 0.96, 0.2, 8), side < 0 ? pink : cyan);
      trim.position.y = 1.2;
      pillar.add(trim);
      const cap = new THREE.Mesh(new THREE.ConeGeometry(0.85, 1.2, 8), light);
      cap.position.y = 12.4;
      pillar.add(cap);
      gate.add(pillar);
    }

    const bannerTex = makeCanvasTexture(1024, 256, (ctx, w, h) => {
      const g = ctx.createLinearGradient(0, 0, w, 0);
      g.addColorStop(0, '#ff2d7e');
      g.addColorStop(0.48, '#ff9f43');
      g.addColorStop(1, '#54f7ff');
      ctx.fillStyle = '#100924';
      ctx.fillRect(0, 0, w, h);
      ctx.fillStyle = g;
      ctx.fillRect(0, 0, w, 8);
      ctx.fillRect(0, h - 8, w, 8);
      ctx.font = '900 88px "Arial Black", sans-serif';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillStyle = '#fff4df';
      ctx.fillText('GRAVITY CUP', w / 2, h / 2 - 10);
      ctx.font = '900 24px "Arial Black", sans-serif';
      ctx.fillStyle = '#54f7ff';
      ctx.letterSpacing = '12px';
      ctx.fillText('ORBITAL CIRCUIT  //  SECTOR 01', w / 2, h / 2 + 62);
    });

    const banner = new THREE.Mesh(
      new THREE.PlaneGeometry(22.4, 5.6),
      new THREE.MeshStandardMaterial({
        map: bannerTex,
        emissiveMap: bannerTex,
        emissive: 0xffffff,
        emissiveIntensity: 0.24,
        roughness: 0.5,
        metalness: 0.2,
        side: THREE.DoubleSide,
      })
    );
    banner.position.y = 11.5;
    gate.add(banner);

    const topGlow = new THREE.Mesh(new THREE.BoxGeometry(22.8, 0.16, 0.16), cyan);
    topGlow.position.set(0, 14.3, 0);
    gate.add(topGlow);
    const bottomGlow = new THREE.Mesh(new THREE.BoxGeometry(22.8, 0.12, 0.12), pink);
    bottomGlow.position.set(0, 8.65, 0);
    gate.add(bottomGlow);

    // Countdown pods above the banner.
    const pods = [];
    for (let i = 0; i < 3; i++) {
      const pod = new THREE.Mesh(
        new THREE.SphereGeometry(0.3, 10, 8),
        new THREE.MeshBasicMaterial({ color: 0x25173f, toneMapped: false })
      );
      pod.position.set((i - 1) * 1.3, 14.9, 0);
      gate.add(pod);
      pods.push(pod);
    }

    this.startGate = gate;
    this.startPods = pods;
    this.group.add(gate);
  }

  _buildGravityRings() {
    const ringMatA = new THREE.MeshStandardMaterial({
      color: 0x281148,
      emissive: 0x54f7ff,
      emissiveIntensity: 2.5,
      roughness: 0.3,
      metalness: 0.6,
    });
    const ringMatB = new THREE.MeshStandardMaterial({
      color: 0x3c103d,
      emissive: 0xff2d7e,
      emissiveIntensity: 2.5,
      roughness: 0.3,
      metalness: 0.6,
    });
    this.rings = [];
    const spots = [
      [0.305, 20.5, ringMatA],
      [0.335, 21.5, ringMatB],
      [0.365, 22.2, ringMatA],
      [0.395, 21.5, ringMatB],
      [0.425, 20.5, ringMatA],
      [0.615, 20.5, ringMatB],
      [0.645, 21.5, ringMatA],
      [0.675, 22.2, ringMatB],
      [0.705, 21.5, ringMatA],
      [0.735, 20.5, ringMatB],
    ];
    for (const [u, radius, mat] of spots) {
      const f = this.getFrame(u);
      const group = new THREE.Group();
      group.position.copy(f.pos);
      group.quaternion.copy(f.quat);
      const torus = new THREE.Mesh(new THREE.TorusGeometry(radius, 0.28, 6, 64), mat);
      group.add(torus);
      const inner = new THREE.Mesh(
        new THREE.TorusGeometry(radius - 2.2, 0.08, 4, 64),
        new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.35, toneMapped: false })
      );
      group.add(inner);
      this.group.add(group);
      this.rings.push({ u, group, torus, inner });
    }
  }

  _buildBoostPads() {
    const tex = makeCanvasTexture(256, 512, (ctx, w, h) => {
      ctx.clearRect(0, 0, w, h);
      for (let i = 0; i < 3; i++) {
        const y = 90 + i * 135;
        ctx.beginPath();
        ctx.moveTo(42, y);
        ctx.lineTo(w / 2, y + 88);
        ctx.lineTo(w - 42, y);
        ctx.lineTo(w - 42, y + 50);
        ctx.lineTo(w / 2, y + 138);
        ctx.lineTo(42, y + 50);
        ctx.closePath();
        const g = ctx.createLinearGradient(0, y, 0, y + 140);
        g.addColorStop(0, '#fff7d0');
        g.addColorStop(0.4, '#54f7ff');
        g.addColorStop(1, '#ff2d7e');
        ctx.fillStyle = g;
        ctx.fill();
        ctx.shadowColor = '#54f7ff';
        ctx.shadowBlur = 22;
        ctx.strokeStyle = 'rgba(255,255,255,.9)';
        ctx.lineWidth = 6;
        ctx.stroke();
        ctx.shadowBlur = 0;
      }
    });
    const mat = new THREE.MeshBasicMaterial({
      map: tex,
      transparent: true,
      opacity: 0.92,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
      toneMapped: false,
    });
    this.boostPads = [];
    const pads = [
      [0.128, -3.2],
      [0.128, 3.2],
      [0.505, 0],
      [0.815, -3.4],
      [0.815, 3.4],
    ];
    for (const [u, lat] of pads) {
      const f = this.getFrame(u);
      const group = new THREE.Group();
      group.position.copy(f.pos).addScaledVector(f.up, 0.05);
      group.quaternion.copy(f.quat);
      const mesh = new THREE.Mesh(new THREE.PlaneGeometry(5.4, 8.4).rotateX(-Math.PI / 2), mat);
      mesh.position.x = lat;
      group.add(mesh);
      const glow = new THREE.Mesh(
        new THREE.PlaneGeometry(6.6, 10.2).rotateX(-Math.PI / 2),
        new THREE.MeshBasicMaterial({
          map: tex,
          transparent: true,
          opacity: 0.22,
          blending: THREE.AdditiveBlending,
          depthWrite: false,
          toneMapped: false,
        })
      );
      glow.position.set(lat, -0.01, 0);
      group.add(glow);
      this.group.add(group);
      this.boostPads.push({ u, lat, width: 5.4, length: 8.4, group, mesh, glow });
    }
  }

  _buildMapPoints() {
    this.mapPoints = [];
    const n = 220;
    let minX = Infinity;
    let maxX = -Infinity;
    let minZ = Infinity;
    let maxZ = -Infinity;
    for (let i = 0; i < n; i++) {
      const p = this.curve.getPointAt(i / n);
      this.mapPoints.push([p.x, p.z]);
      minX = Math.min(minX, p.x);
      maxX = Math.max(maxX, p.x);
      minZ = Math.min(minZ, p.z);
      maxZ = Math.max(maxZ, p.z);
    }
    this.mapBounds = { minX, maxX, minZ, maxZ };
    this.gravityMapZones = [
      [0.29, 0.43],
      [0.6, 0.74],
    ];
  }

  _buildDecorations() {
    // Tiny glowing beacons along the track shoulder.
    const beaconMat = new THREE.MeshBasicMaterial({ color: 0x54f7ff, toneMapped: false });
    const beaconMatB = new THREE.MeshBasicMaterial({ color: 0xff2d7e, toneMapped: false });
    const geo = new THREE.CylinderGeometry(0.06, 0.12, 1.4, 5);
    const count = 54;
    for (let i = 0; i < count; i++) {
      const u = i / count + 0.004;
      const f = this.getFrame(u);
      const side = i % 2 === 0 ? -1 : 1;
      const beacon = new THREE.Mesh(geo, side < 0 ? beaconMatB : beaconMat);
      beacon.position.copy(f.pos).addScaledVector(f.right, side * (this.edgeHalf + 0.35)).addScaledVector(f.up, 0.7);
      beacon.quaternion.copy(f.quat);
      this.group.add(beacon);
    }
  }
}

import * as THREE from 'three';
import { mulberry32, radialGlowTexture } from './utils.js';

export class World {
  constructor(scene, renderer) {
    this.scene = scene;
    this.renderer = renderer;
    this.group = new THREE.Group();
    this.scene.add(this.group);
    this.animated = [];
    this.clouds = [];
    this.islands = [];
    this.time = 0;
    this._buildSky();
    this._buildStars();
    this._buildClouds();
    this._buildIslands();
    this._buildPlanet();
    this._buildDust();
  }

  _buildSky() {
    const skyGeo = new THREE.SphereGeometry(1100, 40, 24);
    const skyMat = new THREE.ShaderMaterial({
      side: THREE.BackSide,
      depthWrite: false,
      fog: false,
      uniforms: {
        topColor: { value: new THREE.Color(0x10082f) },
        midColor: { value: new THREE.Color(0x52217a) },
        horizonColor: { value: new THREE.Color(0xff6f83) },
        lowColor: { value: new THREE.Color(0xffb56b) },
        sunDir: { value: new THREE.Vector3(-0.42, 0.28, -0.86).normalize() },
        sunColor: { value: new THREE.Color(0xfff2c8) },
      },
      vertexShader: `
        varying vec3 vWorld;
        void main() {
          vWorld = position;
          gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
        }
      `,
      fragmentShader: `
        uniform vec3 topColor;
        uniform vec3 midColor;
        uniform vec3 horizonColor;
        uniform vec3 lowColor;
        uniform vec3 sunDir;
        uniform vec3 sunColor;
        varying vec3 vWorld;

        float hash(vec2 p) {
          return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
        }

        void main() {
          vec3 dir = normalize(vWorld);
          float h = dir.y;
          vec3 col = mix(horizonColor, midColor, smoothstep(0.0, 0.34, h));
          col = mix(col, topColor, smoothstep(0.3, 0.85, h));
          col = mix(lowColor, col, smoothstep(-0.28, 0.06, h));

          float sun = max(dot(dir, sunDir), 0.0);
          col += sunColor * pow(sun, 700.0) * 2.6;
          col += sunColor * pow(sun, 16.0) * 0.18;
          col += vec3(1.0, 0.36, 0.55) * pow(max(-dir.y + 0.08, 0.0), 4.0) * 0.08;

          // Subtle atmospheric banding.
          col += 0.025 * sin(h * 85.0 + dir.x * 7.0) * smoothstep(0.0, 0.25, h);
          gl_FragColor = vec4(col, 1.0);
        }
      `,
    });
    const sky = new THREE.Mesh(skyGeo, skyMat);
    sky.renderOrder = -100;
    this.scene.add(sky);
    this.sky = sky;

    const sunGlow = new THREE.Sprite(
      new THREE.SpriteMaterial({
        map: radialGlowTexture('rgba(255,240,190,.95)', 'rgba(255,120,120,0)'),
        transparent: true,
        blending: THREE.AdditiveBlending,
        depthWrite: false,
        depthTest: false,
        fog: false,
      })
    );
    sunGlow.position.copy(skyMat.uniforms.sunDir.value).multiplyScalar(760);
    sunGlow.scale.set(230, 230, 1);
    sunGlow.renderOrder = -90;
    this.scene.add(sunGlow);
    this.sunGlow = sunGlow;
  }

  _buildStars() {
    const rng = mulberry32(7);
    const positions = [];
    const colors = [];
    const color = new THREE.Color();
    for (let i = 0; i < 700; i++) {
      const theta = rng() * Math.PI * 2;
      const phi = Math.acos(0.15 + rng() * 0.85);
      const r = 880 + rng() * 120;
      const x = Math.sin(phi) * Math.cos(theta) * r;
      const y = Math.cos(phi) * r;
      const z = Math.sin(phi) * Math.sin(theta) * r;
      positions.push(x, y, z);
      color.setHSL(0.55 + rng() * 0.22, 0.45, 0.72 + rng() * 0.28);
      colors.push(color.r, color.g, color.b);
    }
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
    geo.setAttribute('color', new THREE.Float32BufferAttribute(colors, 3));
    const mat = new THREE.PointsMaterial({
      size: 2.2,
      vertexColors: true,
      transparent: true,
      opacity: 0.8,
      depthWrite: false,
      blending: THREE.AdditiveBlending,
      fog: false,
      sizeAttenuation: false,
    });
    const stars = new THREE.Points(geo, mat);
    stars.renderOrder = -80;
    this.scene.add(stars);
    this.stars = stars;
  }

  _buildClouds() {
    const rng = mulberry32(42);
    const geo = new THREE.IcosahedronGeometry(1, 1);
    const mats = [
      new THREE.MeshStandardMaterial({ color: 0xffe8ec, roughness: 1, flatShading: true, emissive: 0x3a1e42, emissiveIntensity: 0.35 }),
      new THREE.MeshStandardMaterial({ color: 0xffc9d8, roughness: 1, flatShading: true, emissive: 0x4a1e42, emissiveIntensity: 0.35 }),
      new THREE.MeshStandardMaterial({ color: 0xd7c8ff, roughness: 1, flatShading: true, emissive: 0x2d1a52, emissiveIntensity: 0.35 }),
      new THREE.MeshStandardMaterial({ color: 0xfff1d7, roughness: 1, flatShading: true, emissive: 0x4b2b37, emissiveIntensity: 0.28 }),
    ];

    const makeCluster = (radius, y, scale, opacity = 1) => {
      const cluster = new THREE.Group();
      cluster.position.set(
        Math.cos(radius.angle) * radius.dist,
        y,
        Math.sin(radius.angle) * radius.dist
      );
      const count = 3 + Math.floor(rng() * 5);
      for (let i = 0; i < count; i++) {
        const mesh = new THREE.Mesh(geo, mats[Math.floor(rng() * mats.length)]);
        const s = scale * (0.55 + rng() * 0.75);
        mesh.scale.set(s * (1.1 + rng() * 0.6), s * (0.55 + rng() * 0.3), s * (0.85 + rng() * 0.5));
        mesh.position.set((rng() - 0.5) * scale * 3.2, (rng() - 0.5) * scale * 0.65, (rng() - 0.5) * scale * 2.3);
        mesh.rotation.set(rng() * 0.4, rng() * Math.PI, rng() * 0.2);
        cluster.add(mesh);
      }
      cluster.userData.drift = 0.2 + rng() * 0.6;
      cluster.userData.phase = rng() * Math.PI * 2;
      this.clouds.push(cluster);
      this.group.add(cluster);
      return cluster;
    };

    for (let i = 0; i < 26; i++) {
      makeCluster(
        { angle: (i / 26) * Math.PI * 2 + rng() * 0.22, dist: 180 + rng() * 330 },
        -28 + rng() * 120,
        9 + rng() * 16
      );
    }

    // Cloud ocean below the circuit.
    for (let i = 0; i < 34; i++) {
      makeCluster(
        { angle: rng() * Math.PI * 2, dist: 40 + rng() * 310 },
        -70 - rng() * 35,
        22 + rng() * 26
      );
    }

    // A few close, soft clouds that frame the track.
    makeCluster({ angle: 2.55, dist: 128 }, 28, 10);
    makeCluster({ angle: 5.8, dist: 132 }, 18, 12);
    makeCluster({ angle: 0.25, dist: 165 }, 36, 11);
  }

  _buildIslands() {
    const rng = mulberry32(1337);
    const rockMat = new THREE.MeshStandardMaterial({
      color: 0x3b245d,
      roughness: 0.92,
      metalness: 0.08,
      flatShading: true,
    });
    const rockMatDark = new THREE.MeshStandardMaterial({
      color: 0x24153f,
      roughness: 0.95,
      metalness: 0.06,
      flatShading: true,
    });
    const grassMats = [
      new THREE.MeshStandardMaterial({ color: 0x36c996, roughness: 0.9, flatShading: true, emissive: 0x0c3b38, emissiveIntensity: 0.4 }),
      new THREE.MeshStandardMaterial({ color: 0x67e0b2, roughness: 0.9, flatShading: true, emissive: 0x0c3b38, emissiveIntensity: 0.4 }),
      new THREE.MeshStandardMaterial({ color: 0x8a72e8, roughness: 0.9, flatShading: true, emissive: 0x241252, emissiveIntensity: 0.35 }),
    ];
    const crystalMats = [
      new THREE.MeshStandardMaterial({ color: 0xff8bd0, emissive: 0xff2d7e, emissiveIntensity: 1.8, roughness: 0.2, metalness: 0.35, flatShading: true }),
      new THREE.MeshStandardMaterial({ color: 0x9bfbff, emissive: 0x54f7ff, emissiveIntensity: 1.8, roughness: 0.2, metalness: 0.35, flatShading: true }),
      new THREE.MeshStandardMaterial({ color: 0xffe29b, emissive: 0xffb84d, emissiveIntensity: 1.5, roughness: 0.2, metalness: 0.35, flatShading: true }),
    ];
    const trunkMat = new THREE.MeshStandardMaterial({ color: 0x6a3b51, roughness: 0.95, flatShading: true });
    const leafMat = new THREE.MeshStandardMaterial({ color: 0x27a67c, roughness: 0.9, flatShading: true, emissive: 0x0c3b38, emissiveIntensity: 0.35 });
    const leafMatB = new THREE.MeshStandardMaterial({ color: 0xff5b9d, roughness: 0.9, flatShading: true, emissive: 0x4b1235, emissiveIntensity: 0.4 });

    const makeIsland = (radius, height, x, y, z, options = {}) => {
      const group = new THREE.Group();
      group.position.set(x, y, z);
      const segments = 7 + Math.floor(rng() * 3);

      const underside = new THREE.Mesh(new THREE.ConeGeometry(radius * 0.92, height, segments, 1), rockMat);
      underside.rotation.x = Math.PI;
      underside.position.y = -height / 2 + 1.3;
      underside.rotation.y = rng() * Math.PI;
      group.add(underside);

      const rim = new THREE.Mesh(new THREE.CylinderGeometry(radius, radius * 0.86, 2.5, segments), rockMatDark);
      rim.position.y = 0.2;
      group.add(rim);

      const top = new THREE.Mesh(new THREE.CylinderGeometry(radius * 0.94, radius * 0.99, 1.25, segments), grassMats[Math.floor(rng() * grassMats.length)]);
      top.position.y = 1.65;
      group.add(top);

      const crystalCount = options.crystals ?? 1 + Math.floor(rng() * 3);
      for (let i = 0; i < crystalCount; i++) {
        const angle = rng() * Math.PI * 2;
        const dist = rng() * radius * 0.55;
        const size = radius * (0.08 + rng() * 0.12);
        const crystal = new THREE.Mesh(
          new THREE.ConeGeometry(size * 0.6, size * 3.5, 5),
          crystalMats[Math.floor(rng() * crystalMats.length)]
        );
        crystal.position.set(Math.cos(angle) * dist, 2.2 + size * 1.7, Math.sin(angle) * dist);
        crystal.rotation.set((rng() - 0.5) * 0.35, rng() * Math.PI, (rng() - 0.5) * 0.35);
        group.add(crystal);
        this.animated.push({ mesh: crystal, baseY: crystal.position.y, phase: rng() * 6, amp: 0.12, speed: 0.7 });
      }

      const treeCount = options.trees ?? Math.floor(rng() * 3);
      for (let i = 0; i < treeCount; i++) {
        const angle = rng() * Math.PI * 2;
        const dist = radius * (0.25 + rng() * 0.48);
        const tree = new THREE.Group();
        tree.position.set(Math.cos(angle) * dist, 2.2, Math.sin(angle) * dist);
        const th = radius * (0.15 + rng() * 0.16);
        const trunk = new THREE.Mesh(new THREE.CylinderGeometry(th * 0.07, th * 0.11, th, 5), trunkMat);
        trunk.position.y = th / 2;
        tree.add(trunk);
        const crown = new THREE.Mesh(new THREE.IcosahedronGeometry(th * 0.42, 0), rng() > 0.7 ? leafMatB : leafMat);
        crown.position.y = th * 1.02;
        crown.scale.y = 1.2;
        tree.add(crown);
        group.add(tree);
      }

      if (options.arch) {
        const archMat = new THREE.MeshStandardMaterial({
          color: 0x2a1552,
          emissive: options.archColor ?? 0x54f7ff,
          emissiveIntensity: 1.5,
          metalness: 0.7,
          roughness: 0.3,
        });
        const arch = new THREE.Mesh(new THREE.TorusGeometry(radius * 0.55, radius * 0.03, 6, 30, Math.PI), archMat);
        arch.position.y = 2.2;
        arch.rotation.z = Math.PI;
        group.add(arch);
      }

      group.userData.baseY = y;
      group.userData.phase = rng() * Math.PI * 2;
      group.userData.bob = 0.6 + rng() * 1.1;
      this.islands.push(group);
      this.group.add(group);
      return group;
    };

    // Outer ring of floating islands.
    const islandData = [
      [42, 52, 205, 8, -50, { trees: 4, crystals: 2 }],
      [30, 42, -195, 30, -35, { trees: 2, crystals: 2 }],
      [34, 48, 55, -18, -240, { trees: 3, crystals: 3 }],
      [26, 36, -215, 4, 120, { trees: 2, crystals: 1 }],
      [48, 60, 190, -20, 150, { trees: 4, crystals: 3 }],
      [22, 30, -165, 44, 185, { trees: 1, crystals: 2 }],
      [38, 46, 10, -28, 235, { trees: 3, crystals: 2 }],
      [25, 34, 250, 40, -120, { trees: 2, crystals: 2 }],
      [20, 28, -255, 12, -130, { trees: 1, crystals: 1 }],
      [32, 40, 245, 5, 50, { trees: 2, crystals: 2 }],
    ];
    for (const [r, h, x, y, z, opts] of islandData) {
      makeIsland(r, h, x, y, z, opts);
    }

    // Central spectacle below the orbital circuit.
    const center = makeIsland(56, 92, -10, -46, -48, { trees: 6, crystals: 5, arch: true, archColor: 0xff2d7e });
    const bigCrystal = new THREE.Mesh(
      new THREE.ConeGeometry(7, 46, 6),
      new THREE.MeshStandardMaterial({
        color: 0xaefcff,
        emissive: 0x54f7ff,
        emissiveIntensity: 2.3,
        roughness: 0.12,
        metalness: 0.45,
        transparent: true,
        opacity: 0.92,
        flatShading: true,
      })
    );
    bigCrystal.position.set(0, 24, 0);
    bigCrystal.rotation.z = 0.12;
    center.add(bigCrystal);
    this.animated.push({ mesh: bigCrystal, baseY: 24, phase: 1, amp: 0.7, speed: 0.5 });

    const halo = new THREE.Mesh(
      new THREE.TorusGeometry(15, 0.5, 6, 64),
      new THREE.MeshBasicMaterial({ color: 0xff6fb5, transparent: true, opacity: 0.55, toneMapped: false })
    );
    halo.position.set(0, 26, 0);
    halo.rotation.x = Math.PI / 2.6;
    center.add(halo);
    this.animated.push({ mesh: halo, baseY: 26, phase: 0, amp: 0.4, speed: 0.4, spin: 0.16 });

    // A small cluster of floating rocks.
    for (let i = 0; i < 14; i++) {
      const angle = rng() * Math.PI * 2;
      const dist = 120 + rng() * 180;
      const s = 2 + rng() * 7;
      const rock = new THREE.Mesh(new THREE.DodecahedronGeometry(s, 0), i % 3 === 0 ? rockMat : rockMatDark);
      rock.position.set(Math.cos(angle) * dist, -25 + rng() * 110, Math.sin(angle) * dist);
      rock.rotation.set(rng() * 3, rng() * 3, rng() * 3);
      this.group.add(rock);
      this.animated.push({ mesh: rock, baseY: rock.position.y, phase: rng() * 6, amp: 0.4 + rng() * 0.8, speed: 0.2 + rng() * 0.3, spin: 0.03 });
    }

    // Whimsical balloons.
    const balloonColors = [0xff2d7e, 0x54f7ff, 0xffd166];
    for (let i = 0; i < 3; i++) {
      const balloon = new THREE.Group();
      const angle = 1.1 + i * 2.1;
      balloon.position.set(Math.cos(angle) * 145, 35 + i * 9, Math.sin(angle) * 145);
      const canopy = new THREE.Mesh(
        new THREE.SphereGeometry(3.4, 10, 8),
        new THREE.MeshStandardMaterial({
          color: balloonColors[i],
          emissive: balloonColors[i],
          emissiveIntensity: 0.18,
          roughness: 0.6,
          flatShading: true,
        })
      );
      canopy.scale.y = 1.15;
      balloon.add(canopy);
      const basket = new THREE.Mesh(new THREE.CylinderGeometry(0.8, 0.65, 1.2, 6), trunkMat);
      basket.position.y = -4.4;
      balloon.add(basket);
      for (let j = 0; j < 4; j++) {
        const rope = new THREE.Mesh(
          new THREE.CylinderGeometry(0.02, 0.02, 2.5, 3),
          new THREE.MeshBasicMaterial({ color: 0xfff0d0 })
        );
        rope.position.set(Math.cos((j / 4) * Math.PI * 2) * 0.8, -2.8, Math.sin((j / 4) * Math.PI * 2) * 0.8);
        balloon.add(rope);
      }
      this.group.add(balloon);
      this.animated.push({ mesh: balloon, baseY: balloon.position.y, phase: rng() * 6, amp: 1.2, speed: 0.35 });
    }
  }

  _buildPlanet() {
    const planet = new THREE.Mesh(
      new THREE.SphereGeometry(42, 24, 16),
      new THREE.MeshStandardMaterial({
        color: 0xffb0c8,
        emissive: 0x8d2f6d,
        emissiveIntensity: 0.55,
        roughness: 0.85,
        metalness: 0.05,
        flatShading: true,
      })
    );
    planet.position.set(-460, 230, -680);
    this.scene.add(planet);

    const ring = new THREE.Mesh(
      new THREE.TorusGeometry(66, 2.8, 4, 64),
      new THREE.MeshBasicMaterial({ color: 0xffd6b0, transparent: true, opacity: 0.45, toneMapped: false })
    );
    ring.position.copy(planet.position);
    ring.rotation.x = 1.1;
    ring.rotation.z = 0.3;
    this.scene.add(ring);
    this.planet = planet;
    this.planetRing = ring;
  }

  _buildDust() {
    const rng = mulberry32(9001);
    const count = 420;
    const positions = new Float32Array(count * 3);
    const colors = new Float32Array(count * 3);
    const color = new THREE.Color();
    for (let i = 0; i < count; i++) {
      const angle = rng() * Math.PI * 2;
      const dist = 30 + rng() * 210;
      positions[i * 3] = Math.cos(angle) * dist;
      positions[i * 3 + 1] = -20 + rng() * 100;
      positions[i * 3 + 2] = Math.sin(angle) * dist;
      color.setHSL(0.5 + rng() * 0.35, 0.85, 0.65);
      colors[i * 3] = color.r;
      colors[i * 3 + 1] = color.g;
      colors[i * 3 + 2] = color.b;
    }
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    geo.setAttribute('color', new THREE.BufferAttribute(colors, 3));
    const mat = new THREE.PointsMaterial({
      size: 0.5,
      vertexColors: true,
      transparent: true,
      opacity: 0.65,
      depthWrite: false,
      blending: THREE.AdditiveBlending,
      sizeAttenuation: true,
    });
    this.dust = new THREE.Points(geo, mat);
    this.scene.add(this.dust);
  }

  update(dt, elapsed) {
    this.time += dt;
    for (const c of this.clouds) {
      c.position.x += Math.sin(this.time * 0.06 + c.userData.phase) * dt * 0.16;
      c.position.y += Math.cos(this.time * 0.08 + c.userData.phase) * dt * 0.08;
    }
    for (const i of this.islands) {
      i.position.y = i.userData.baseY + Math.sin(this.time * 0.22 + i.userData.phase) * i.userData.bob;
    }
    for (const a of this.animated) {
      a.mesh.position.y = a.baseY + Math.sin(this.time * a.speed + a.phase) * a.amp;
      if (a.spin) a.mesh.rotation.y += dt * a.spin;
    }
    if (this.dust) {
      this.dust.rotation.y = this.time * 0.012;
      this.dust.rotation.x = Math.sin(this.time * 0.03) * 0.02;
    }
    if (this.planetRing) this.planetRing.rotation.z += dt * 0.004;
    if (this.sunGlow) {
      const s = 225 + Math.sin(this.time * 0.5) * 8;
      this.sunGlow.scale.set(s, s, 1);
    }
    if (this.stars) this.stars.rotation.y = this.time * 0.0015;
  }
}

import * as THREE from 'three';
import { RoundedBoxGeometry } from 'three/addons/geometries/RoundedBoxGeometry.js';
import { radialGlowTexture } from './utils.js';

const wheelGeo = new THREE.CylinderGeometry(0.43, 0.43, 0.34, 12);
wheelGeo.rotateZ(Math.PI / 2);
const hubGeo = new THREE.CylinderGeometry(0.19, 0.19, 0.37, 10);
hubGeo.rotateZ(Math.PI / 2);
const tireMat = new THREE.MeshStandardMaterial({ color: 0x181226, roughness: 0.9, metalness: 0.1 });
const darkMat = new THREE.MeshStandardMaterial({ color: 0x1a1430, roughness: 0.55, metalness: 0.35 });
const chromeMat = new THREE.MeshStandardMaterial({ color: 0xb9b6d7, roughness: 0.25, metalness: 0.9 });
const shadowTex = radialGlowTexture('rgba(0,0,0,.65)', 'rgba(0,0,0,0)');
const glowTex = radialGlowTexture('rgba(255,255,255,.7)', 'rgba(255,255,255,0)');
const flameGeo = new THREE.ConeGeometry(0.2, 1.25, 6);
flameGeo.rotateX(-Math.PI / 2);
flameGeo.translate(0, 0, 0.55);

export function createKart({
  color = 0xff3b5c,
  accent = 0xffd166,
  suit = 0xfff0e2,
  number = 1,
  isPlayer = false,
}) {
  const root = new THREE.Group();
  const body = new THREE.Group();
  root.add(body);

  const paint = new THREE.MeshStandardMaterial({ color, roughness: 0.32, metalness: 0.55 });
  const paintLight = new THREE.MeshStandardMaterial({ color: accent, roughness: 0.35, metalness: 0.5 });
  const suitMat = new THREE.MeshStandardMaterial({ color: suit, roughness: 0.75, metalness: 0.05 });
  const helmetMat = new THREE.MeshStandardMaterial({ color, roughness: 0.28, metalness: 0.6 });
  const visorMat = new THREE.MeshStandardMaterial({
    color: 0x12162c,
    roughness: 0.08,
    metalness: 0.9,
    emissive: 0x102a4d,
    emissiveIntensity: 0.4,
  });
  const glowMat = new THREE.MeshBasicMaterial({ color: accent, toneMapped: false });
  const headlightMat = new THREE.MeshBasicMaterial({ color: 0xfff3c9, toneMapped: false });

  const chassis = new THREE.Mesh(new RoundedBoxGeometry(1.9, 0.46, 2.9, 4, 0.14), paint);
  chassis.position.y = 0.58;
  body.add(chassis);

  const belly = new THREE.Mesh(new RoundedBoxGeometry(1.55, 0.24, 2.25, 3, 0.1), darkMat);
  belly.position.set(0, 0.36, 0.05);
  body.add(belly);

  const nose = new THREE.Mesh(new RoundedBoxGeometry(1.25, 0.3, 1.1, 4, 0.12), paint);
  nose.position.set(0, 0.53, -1.62);
  nose.rotation.x = -0.08;
  body.add(nose);

  const noseTip = new THREE.Mesh(new RoundedBoxGeometry(0.6, 0.22, 0.32, 3, 0.06), paintLight);
  noseTip.position.set(0, 0.5, -2.18);
  body.add(noseTip);

  for (const side of [-1, 1]) {
    const pod = new THREE.Mesh(new RoundedBoxGeometry(0.44, 0.38, 1.35, 3, 0.1), paintLight);
    pod.position.set(side * 1.03, 0.56, 0.15);
    body.add(pod);

    const sideLight = new THREE.Mesh(new THREE.BoxGeometry(0.05, 0.09, 0.72), glowMat);
    sideLight.position.set(side * 1.27, 0.59, 0.2);
    body.add(sideLight);

    const headlight = new THREE.Mesh(new THREE.SphereGeometry(0.12, 8, 6), headlightMat);
    headlight.position.set(side * 0.5, 0.58, -2.06);
    body.add(headlight);
  }

  const seatBack = new THREE.Mesh(new RoundedBoxGeometry(0.92, 0.88, 0.26, 3, 0.1), darkMat);
  seatBack.position.set(0, 1.0, 0.77);
  seatBack.rotation.x = 0.12;
  body.add(seatBack);

  const seatBase = new THREE.Mesh(new RoundedBoxGeometry(0.88, 0.22, 0.85, 3, 0.08), darkMat);
  seatBase.position.set(0, 0.84, 0.43);
  body.add(seatBase);

  const engine = new THREE.Mesh(new THREE.CylinderGeometry(0.3, 0.36, 0.72, 8), darkMat);
  engine.rotation.x = Math.PI / 2;
  engine.position.set(0, 0.73, 1.35);
  body.add(engine);

  const engineRing = new THREE.Mesh(new THREE.TorusGeometry(0.31, 0.045, 5, 12), paintLight);
  engineRing.position.set(0, 0.73, 1.72);
  body.add(engineRing);

  const spoilerBar = new THREE.Mesh(new RoundedBoxGeometry(1.95, 0.13, 0.42, 3, 0.05), paint);
  spoilerBar.position.set(0, 1.36, 1.33);
  body.add(spoilerBar);

  for (const side of [-1, 1]) {
    const strut = new THREE.Mesh(new THREE.BoxGeometry(0.09, 0.58, 0.13), darkMat);
    strut.position.set(side * 0.72, 1.08, 1.36);
    strut.rotation.z = side * 0.12;
    body.add(strut);
  }

  const bumper = new THREE.Mesh(new RoundedBoxGeometry(2.0, 0.2, 0.22, 3, 0.05), darkMat);
  bumper.position.set(0, 0.47, 1.6);
  body.add(bumper);

  // Driver.
  const driver = new THREE.Group();
  driver.position.set(0, 0.7, 0.34);
  body.add(driver);

  const torso = new THREE.Mesh(new THREE.CapsuleGeometry(0.3, 0.42, 6, 10), suitMat);
  torso.position.y = 0.58;
  torso.rotation.x = -0.16;
  driver.add(torso);

  const belt = new THREE.Mesh(new THREE.CylinderGeometry(0.31, 0.31, 0.12, 10), darkMat);
  belt.position.y = 0.48;
  driver.add(belt);

  const head = new THREE.Mesh(new THREE.SphereGeometry(0.36, 16, 12), suitMat);
  head.position.set(0, 1.1, -0.03);
  driver.add(head);

  const helmet = new THREE.Mesh(new THREE.SphereGeometry(0.41, 16, 12, 0, Math.PI * 2, 0, Math.PI * 0.66), helmetMat);
  helmet.position.set(0, 1.12, -0.02);
  driver.add(helmet);

  const helmetStripe = new THREE.Mesh(new THREE.BoxGeometry(0.1, 0.2, 0.7), paintLight);
  helmetStripe.position.set(0, 1.42, -0.02);
  driver.add(helmetStripe);

  const visor = new THREE.Mesh(new RoundedBoxGeometry(0.55, 0.22, 0.16, 3, 0.06), visorMat);
  visor.position.set(0, 1.13, -0.36);
  driver.add(visor);

  for (const side of [-1, 1]) {
    const arm = new THREE.Mesh(new THREE.CapsuleGeometry(0.085, 0.38, 4, 8), suitMat);
    arm.position.set(side * 0.32, 0.68, -0.25);
    arm.rotation.set(0.75, 0, side * -0.22);
    driver.add(arm);

    const glove = new THREE.Mesh(new THREE.SphereGeometry(0.11, 8, 6), darkMat);
    glove.position.set(side * 0.22, 0.48, -0.58);
    driver.add(glove);
  }

  const wheelRing = new THREE.Mesh(new THREE.TorusGeometry(0.25, 0.055, 6, 14), darkMat);
  wheelRing.position.set(0, 0.55, -0.5);
  wheelRing.rotation.x = Math.PI / 2.4;
  driver.add(wheelRing);

  // Wheels.
  const wheels = [];
  const frontWheels = [];
  for (const [x, z, front] of [
    [-1.02, -1.03, true],
    [1.02, -1.03, true],
    [-1.04, 1.02, false],
    [1.04, 1.02, false],
  ]) {
    const steer = new THREE.Group();
    steer.position.set(x, 0.43, z);
    const spin = new THREE.Group();
    steer.add(spin);
    const tire = new THREE.Mesh(wheelGeo, tireMat);
    spin.add(tire);
    const hub = new THREE.Mesh(hubGeo, paintLight);
    spin.add(hub);
    const cap = new THREE.Mesh(new THREE.CylinderGeometry(0.07, 0.07, 0.39, 6).rotateZ(Math.PI / 2), glowMat);
    spin.add(cap);
    body.add(steer);
    wheels.push(spin);
    if (front) frontWheels.push(steer);
  }

  // Exhausts and flames.
  const flames = [];
  for (const side of [-1, 1]) {
    const pipe = new THREE.Mesh(new THREE.CylinderGeometry(0.13, 0.17, 0.4, 8), chromeMat);
    pipe.rotation.x = Math.PI / 2;
    pipe.position.set(side * 0.43, 0.6, 1.76);
    body.add(pipe);

    const flame = new THREE.Mesh(
      flameGeo,
      new THREE.MeshBasicMaterial({
        color: 0x54f7ff,
        transparent: true,
        opacity: 0.9,
        blending: THREE.AdditiveBlending,
        depthWrite: false,
        toneMapped: false,
      })
    );
    flame.position.set(side * 0.43, 0.6, 1.86);
    flame.scale.set(0.01, 0.01, 0.01);
    body.add(flame);
    flames.push(flame);

    const flameCore = new THREE.Mesh(
      flameGeo,
      new THREE.MeshBasicMaterial({
        color: 0xffffff,
        transparent: true,
        opacity: 0.9,
        blending: THREE.AdditiveBlending,
        depthWrite: false,
        toneMapped: false,
      })
    );
    flameCore.position.set(side * 0.43, 0.6, 1.87);
    flameCore.scale.setScalar(0.01);
    body.add(flameCore);
    flames.push(flameCore);
  }

  // Glowing hover cushion and contact shadow.
  const glow = new THREE.Mesh(
    new THREE.PlaneGeometry(2.8, 3.6).rotateX(-Math.PI / 2),
    new THREE.MeshBasicMaterial({
      map: glowTex,
      color: accent,
      transparent: true,
      opacity: 0.45,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
      toneMapped: false,
    })
  );
  glow.position.y = 0.05;
  root.add(glow);

  const shadow = new THREE.Mesh(
    new THREE.PlaneGeometry(2.9, 3.7).rotateX(-Math.PI / 2),
    new THREE.MeshBasicMaterial({
      map: shadowTex,
      color: 0x080416,
      transparent: true,
      opacity: 0.5,
      depthWrite: false,
      toneMapped: false,
    })
  );
  shadow.position.y = 0.025;
  root.add(shadow);

  // A little antenna flag.
  const antenna = new THREE.Mesh(new THREE.CylinderGeometry(0.018, 0.018, 1.1, 4), chromeMat);
  antenna.position.set(0.75, 1.5, 1.25);
  antenna.rotation.z = -0.1;
  body.add(antenna);
  const flag = new THREE.Mesh(
    new THREE.PlaneGeometry(0.48, 0.3, 2, 1),
    new THREE.MeshBasicMaterial({ color: accent, side: THREE.DoubleSide, toneMapped: false })
  );
  flag.position.set(0.98, 1.92, 1.25);
  flag.rotation.y = 0.2;
  body.add(flag);

  if (isPlayer) {
    const marker = new THREE.Mesh(
      new THREE.ConeGeometry(0.22, 0.5, 4),
      new THREE.MeshBasicMaterial({ color: 0x54f7ff, toneMapped: false })
    );
    marker.position.set(0, 3.2, 0);
    marker.rotation.x = Math.PI;
    root.add(marker);
    root.userData.marker = marker;
  }

  // Tiny racing number plate.
  const plate = new THREE.Mesh(
    new THREE.PlaneGeometry(0.34, 0.26),
    new THREE.MeshBasicMaterial({ color: 0xfff4df, toneMapped: false })
  );
  plate.position.set(0, 0.73, -2.2);
  body.add(plate);

  root.userData.body = body;
  root.userData.driver = driver;
  root.userData.wheels = wheels;
  root.userData.frontWheels = frontWheels;
  root.userData.flames = flames;
  root.userData.glow = glow;
  root.userData.shadow = shadow;
  root.userData.number = number;
  return root;
}

export function updateKartVisual(kart, {
  steer = 0,
  speed = 0,
  drifting = false,
  boosting = false,
  dt = 0.016,
  time = 0,
  spinSpeed = 0,
  isPlayer = false,
}) {
  const body = kart.userData.body;
  const targetLean = -steer * (drifting ? 0.2 : 0.1);
  body.rotation.z += (targetLean - body.rotation.z) * Math.min(1, dt * 8);
  const targetPitch = boosting ? -0.06 : 0;
  body.rotation.x += (targetPitch - body.rotation.x) * Math.min(1, dt * 6);
  body.position.y = Math.sin(time * 12 + kart.userData.number) * 0.018;

  for (const wheel of kart.userData.wheels) {
    wheel.rotation.x -= spinSpeed * dt;
  }
  for (const steerGroup of kart.userData.frontWheels) {
    steerGroup.rotation.y += (steer * 0.42 - steerGroup.rotation.y) * Math.min(1, dt * 12);
  }

  const flames = kart.userData.flames;
  const flameScale = boosting ? 1 : 0.01;
  for (let i = 0; i < flames.length; i++) {
    const f = flames[i];
    const isCore = i % 2 === 1;
    const target = flameScale * (isCore ? 0.48 : 1) * (0.88 + Math.sin(time * 55 + i) * 0.12);
    f.scale.x += (target * 0.9 - f.scale.x) * Math.min(1, dt * 18);
    f.scale.y += (target * 0.9 - f.scale.y) * Math.min(1, dt * 18);
    f.scale.z += (target - f.scale.z) * Math.min(1, dt * 18);
    f.material.opacity = boosting ? 0.95 : 0;
  }

  const glow = kart.userData.glow;
  glow.material.opacity = 0.32 + (boosting ? 0.4 : 0) + Math.sin(time * 5) * 0.06;

  if (isPlayer && kart.userData.marker) {
    const marker = kart.userData.marker;
    marker.position.y = 3.25 + Math.sin(time * 3.2) * 0.15;
    marker.rotation.y = time * 1.8;
  }
}

import * as THREE from 'three';
import { mulberry32 } from './utils.js';

export class Particles {
  constructor(scene, count = 1600) {
    this.scene = scene;
    this.count = count;
    this.cursor = 0;
    this.rng = mulberry32(555);
    this.particles = new Array(count);

    this.positions = new Float32Array(count * 3);
    this.colors = new Float32Array(count * 3);
    this.sizes = new Float32Array(count);
    this.alphas = new Float32Array(count);

    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(this.positions, 3));
    geo.setAttribute('color', new THREE.BufferAttribute(this.colors, 3));
    geo.setAttribute('size', new THREE.BufferAttribute(this.sizes, 1));
    geo.setAttribute('alpha', new THREE.BufferAttribute(this.alphas, 1));
    geo.setDrawRange(0, count);

    const mat = new THREE.ShaderMaterial({
      transparent: true,
      depthWrite: false,
      blending: THREE.AdditiveBlending,
      vertexColors: true,
      uniforms: {
        uPixelRatio: { value: Math.min(window.devicePixelRatio, 2) },
      },
      vertexShader: `
        attribute float size;
        attribute float alpha;
        varying vec3 vColor;
        varying float vAlpha;
        uniform float uPixelRatio;
        void main() {
          vColor = color;
          vAlpha = alpha;
          vec4 mvPosition = modelViewMatrix * vec4(position, 1.0);
          gl_PointSize = size * uPixelRatio * (280.0 / max(2.0, -mvPosition.z));
          gl_Position = projectionMatrix * mvPosition;
        }
      `,
      fragmentShader: `
        varying vec3 vColor;
        varying float vAlpha;
        void main() {
          vec2 uv = gl_PointCoord - 0.5;
          float d = length(uv);
          float alpha = smoothstep(0.5, 0.08, d) * vAlpha;
          if (alpha < 0.01) discard;
          gl_FragColor = vec4(vColor, alpha);
        }
      `,
    });

    this.points = new THREE.Points(geo, mat);
    this.points.frustumCulled = false;
    this.points.renderOrder = 8;
    this.scene.add(this.points);

    for (let i = 0; i < count; i++) {
      this.particles[i] = {
        alive: false,
        x: 0, y: 0, z: 0,
        vx: 0, vy: 0, vz: 0,
        life: 0, maxLife: 1,
        size: 1, gravity: 0, drag: 0,
        r: 1, g: 1, b: 1,
      };
      this.sizes[i] = 0;
      this.alphas[i] = 0;
    }
  }

  spawn(x, y, z, opts = {}) {
    const p = this.particles[this.cursor];
    this.cursor = (this.cursor + 1) % this.count;
    const color = opts.color ?? 0xffffff;
    const c = new THREE.Color(color);
    p.alive = true;
    p.x = x;
    p.y = y;
    p.z = z;
    p.vx = opts.vx ?? 0;
    p.vy = opts.vy ?? 0;
    p.vz = opts.vz ?? 0;
    p.life = opts.life ?? 1;
    p.maxLife = p.life;
    p.size = opts.size ?? 1;
    p.gravity = opts.gravity ?? 0;
    p.drag = opts.drag ?? 0.98;
    p.r = c.r;
    p.g = c.g;
    p.b = c.b;
    return p;
  }

  burst(position, opts = {}) {
    const {
      count = 18,
      color = 0xffffff,
      colors = null,
      speed = 6,
      spread = 1,
      life = 0.8,
      size = 1,
      gravity = -7,
      drag = 0.95,
      direction = null,
      up = 1,
    } = opts;
    for (let i = 0; i < count; i++) {
      const theta = this.rng() * Math.PI * 2;
      const phi = Math.acos(this.rng() * 2 - 1);
      let vx = Math.sin(phi) * Math.cos(theta) * speed;
      let vy = Math.cos(phi) * speed * up;
      let vz = Math.sin(phi) * Math.sin(theta) * speed;
      if (direction) {
        vx += direction.x * speed * 0.4;
        vy += direction.y * speed * 0.4;
        vz += direction.z * speed * 0.4;
      }
      const chosen = colors ? colors[Math.floor(this.rng() * colors.length)] : color;
      this.spawn(
        position.x + (this.rng() - 0.5) * spread,
        position.y + (this.rng() - 0.5) * spread,
        position.z + (this.rng() - 0.5) * spread,
        {
          vx,
          vy,
          vz,
          color: chosen,
          life: life * (0.7 + this.rng() * 0.6),
          size: size * (0.7 + this.rng() * 0.8),
          gravity,
          drag,
        }
      );
    }
  }

  spark(position, color, direction, count = 1) {
    for (let i = 0; i < count; i++) {
      this.spawn(
        position.x + (this.rng() - 0.5) * 0.4,
        position.y + (this.rng() - 0.5) * 0.25,
        position.z + (this.rng() - 0.5) * 0.4,
        {
          vx: (this.rng() - 0.5) * 4 - direction.x * 3,
          vy: (this.rng() - 0.5) * 3 + 1.5,
          vz: (this.rng() - 0.5) * 4 - direction.z * 3,
          color,
          life: 0.28 + this.rng() * 0.3,
          size: 0.5 + this.rng() * 0.5,
          gravity: -9,
          drag: 0.92,
        }
      );
    }
  }

  trail(position, color, direction, count = 1, size = 0.8) {
    for (let i = 0; i < count; i++) {
      this.spawn(
        position.x + (this.rng() - 0.5) * 0.7,
        position.y + (this.rng() - 0.5) * 0.4,
        position.z + (this.rng() - 0.5) * 0.7,
        {
          vx: -direction.x * (3 + this.rng() * 4) + (this.rng() - 0.5) * 1.5,
          vy: -direction.y * 2 + (this.rng() - 0.5) * 1.5 + 0.8,
          vz: -direction.z * (3 + this.rng() * 4) + (this.rng() - 0.5) * 1.5,
          color,
          life: 0.28 + this.rng() * 0.35,
          size: size * (0.7 + this.rng() * 0.8),
          gravity: -2,
          drag: 0.94,
        }
      );
    }
  }

  update(dt) {
    const pos = this.positions;
    const col = this.colors;
    const sizes = this.sizes;
    const alphas = this.alphas;
    for (let i = 0; i < this.count; i++) {
      const p = this.particles[i];
      if (!p.alive) {
        alphas[i] = 0;
        continue;
      }
      p.life -= dt;
      if (p.life <= 0) {
        p.alive = false;
        alphas[i] = 0;
        continue;
      }
      p.vy += p.gravity * dt;
      const drag = Math.pow(p.drag, dt * 60);
      p.vx *= drag;
      p.vy *= drag;
      p.vz *= drag;
      p.x += p.vx * dt;
      p.y += p.vy * dt;
      p.z += p.vz * dt;

      const t = p.life / p.maxLife;
      pos[i * 3] = p.x;
      pos[i * 3 + 1] = p.y;
      pos[i * 3 + 2] = p.z;
      col[i * 3] = p.r;
      col[i * 3 + 1] = p.g;
      col[i * 3 + 2] = p.b;
      sizes[i] = p.size * (0.5 + t * 0.7);
      alphas[i] = Math.min(1, t * 2.5) * 0.9;
    }
    this.points.geometry.attributes.position.needsUpdate = true;
    this.points.geometry.attributes.color.needsUpdate = true;
    this.points.geometry.attributes.size.needsUpdate = true;
    this.points.geometry.attributes.alpha.needsUpdate = true;
  }

  setPixelRatio(ratio) {
    this.points.material.uniforms.uPixelRatio.value = ratio;
  }
}

export class AudioEngine {
  constructor() {
    this.ctx = null;
    this.muted = false;
    this.musicOn = false;
    this.musicStep = 0;
    this.musicTimer = null;
    this.ready = false;
  }

  init() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume();
      return;
    }
    const Ctx = window.AudioContext || window.webkitAudioContext;
    if (!Ctx) return;
    this.ctx = new Ctx();
    this.master = this.ctx.createGain();
    this.master.gain.value = this.muted ? 0 : 0.6;
    this.master.connect(this.ctx.destination);

    this.sfx = this.ctx.createGain();
    this.sfx.gain.value = 0.6;
    this.sfx.connect(this.master);

    this.music = this.ctx.createGain();
    this.music.gain.value = 0.15;
    this.music.connect(this.master);

    const comp = this.ctx.createDynamicsCompressor();
    comp.threshold.value = -16;
    comp.knee.value = 22;
    comp.ratio.value = 6;
    this.sfx.disconnect();
    this.sfx.connect(comp);
    comp.connect(this.master);
    this.sfxComp = comp;

    this._buildEngine();
    this.ready = true;
  }

  _buildEngine() {
    const ctx = this.ctx;
    this.engineGain = ctx.createGain();
    this.engineGain.gain.value = 0;
    this.engineFilter = ctx.createBiquadFilter();
    this.engineFilter.type = 'lowpass';
    this.engineFilter.frequency.value = 700;
    this.engineFilter.Q.value = 2.4;
    this.engineGain.connect(this.engineFilter);
    this.engineFilter.connect(this.sfx);

    this.engineOsc1 = ctx.createOscillator();
    this.engineOsc1.type = 'sawtooth';
    this.engineOsc1.frequency.value = 68;
    this.engineOsc1.connect(this.engineGain);
    this.engineOsc1.start();

    this.engineOsc2 = ctx.createOscillator();
    this.engineOsc2.type = 'square';
    this.engineOsc2.frequency.value = 34;
    const g2 = ctx.createGain();
    g2.gain.value = 0.35;
    this.engineOsc2.connect(g2);
    g2.connect(this.engineGain);
    this.engineOsc2.start();

    const noiseBuffer = ctx.createBuffer(1, ctx.sampleRate * 1.5, ctx.sampleRate);
    const data = noiseBuffer.getChannelData(0);
    for (let i = 0; i < data.length; i++) data[i] = Math.random() * 2 - 1;
    this.noiseBuffer = noiseBuffer;
  }

  setMuted(muted) {
    this.muted = muted;
    if (!this.ctx) return;
    this.master.gain.setTargetAtTime(muted ? 0 : 0.6, this.ctx.currentTime, 0.03);
  }

  updateEngine(speed, maxSpeed, boosting, active) {
    if (!this.ready) return;
    const t = this.ctx.currentTime;
    const ratio = Math.min(1.25, speed / Math.max(1, maxSpeed));
    const target = active ? 0.018 + ratio * 0.025 + (boosting ? 0.018 : 0) : 0;
    this.engineGain.gain.setTargetAtTime(target, t, 0.08);
    const freq = 52 + ratio * 110 + (boosting ? 30 : 0);
    this.engineOsc1.frequency.setTargetAtTime(freq, t, 0.07);
    this.engineOsc2.frequency.setTargetAtTime(freq * 0.5 + 1.4, t, 0.07);
    this.engineFilter.frequency.setTargetAtTime(480 + ratio * 1200 + (boosting ? 500 : 0), t, 0.08);
  }

  _tone(freq, duration, type = 'sine', gain = 0.18, slideTo = null, delay = 0) {
    if (!this.ready) return;
    const ctx = this.ctx;
    const t0 = ctx.currentTime + delay;
    const osc = ctx.createOscillator();
    const g = ctx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, t0);
    if (slideTo) osc.frequency.exponentialRampToValueAtTime(Math.max(20, slideTo), t0 + duration);
    g.gain.setValueAtTime(0.0001, t0);
    g.gain.exponentialRampToValueAtTime(gain, t0 + 0.012);
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + duration);
    osc.connect(g);
    g.connect(this.sfx);
    osc.start(t0);
    osc.stop(t0 + duration + 0.03);
  }

  _noise(duration = 0.2, gain = 0.14, freq = 900, delay = 0) {
    if (!this.ready) return;
    const ctx = this.ctx;
    const t0 = ctx.currentTime + delay;
    const src = ctx.createBufferSource();
    src.buffer = this.noiseBuffer;
    const filter = ctx.createBiquadFilter();
    filter.type = 'bandpass';
    filter.frequency.setValueAtTime(freq, t0);
    filter.frequency.exponentialRampToValueAtTime(Math.max(100, freq * 0.25), t0 + duration);
    filter.Q.value = 0.9;
    const g = ctx.createGain();
    g.gain.setValueAtTime(gain, t0);
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + duration);
    src.connect(filter);
    filter.connect(g);
    g.connect(this.sfx);
    src.start(t0);
    src.stop(t0 + duration + 0.05);
  }

  countdown(final = false) {
    if (final) {
      this._tone(660, 0.12, 'square', 0.12);
      this._tone(990, 0.45, 'square', 0.14, 1320, 0.1);
      this._noise(0.5, 0.12, 1800);
    } else {
      this._tone(520, 0.11, 'square', 0.1);
    }
  }

  coin() {
    this._tone(1320, 0.08, 'triangle', 0.1);
    this._tone(1760, 0.13, 'triangle', 0.09, null, 0.05);
  }

  pickup() {
    const notes = [523, 659, 784, 1047];
    notes.forEach((n, i) => this._tone(n, 0.12, 'triangle', 0.08, null, i * 0.045));
  }

  boost() {
    this._noise(0.5, 0.2, 2400);
    this._tone(140, 0.45, 'sawtooth', 0.14, 420);
  }

  driftRelease(level = 1) {
    this._noise(0.22 + level * 0.1, 0.1 + level * 0.04, 1600 + level * 500);
    this._tone(180 + level * 40, 0.2, 'square', 0.08, 300 + level * 80);
  }

  hit() {
    this._noise(0.24, 0.22, 300);
    this._tone(90, 0.2, 'sawtooth', 0.12, 50);
  }

  item() {
    this._tone(420, 0.2, 'sawtooth', 0.1, 840);
    this._noise(0.3, 0.1, 1300);
  }

  shield() {
    this._tone(300, 0.4, 'sine', 0.1, 800);
    this._tone(600, 0.5, 'triangle', 0.06, 1200, 0.08);
  }

  lap() {
    [659, 784, 1047].forEach((n, i) => this._tone(n, 0.18, 'triangle', 0.1, null, i * 0.08));
  }

  finish(win = true) {
    const notes = win ? [523, 659, 784, 1047, 1319, 1568] : [392, 466, 523, 622];
    notes.forEach((n, i) => this._tone(n, 0.3, 'triangle', 0.12, null, i * 0.11));
    if (win) this._noise(0.9, 0.12, 2200, 0.25);
  }

  startMusic() {
    if (!this.ready || this.musicOn) return;
    this.musicOn = true;
    this.musicStep = 0;
    const bass = [0, 0, 7, 0, 5, 0, 3, 7];
    const lead = [12, 15, 19, 22, 19, 15, 12, 10];
    this.musicTimer = setInterval(() => {
      if (!this.musicOn || !this.ctx) return;
      const ctx = this.ctx;
      const t0 = ctx.currentTime + 0.02;
      const step = this.musicStep % 16;
      const root = 55;
      const note = 2 ** ((bass[step % 8] + (step >= 8 ? 2 : 0)) / 12);
      const osc = ctx.createOscillator();
      const g = ctx.createGain();
      osc.type = 'triangle';
      osc.frequency.value = root * note;
      g.gain.setValueAtTime(0.0001, t0);
      g.gain.exponentialRampToValueAtTime(0.12, t0 + 0.02);
      g.gain.exponentialRampToValueAtTime(0.0001, t0 + 0.22);
      osc.connect(g);
      g.connect(this.music);
      osc.start(t0);
      osc.stop(t0 + 0.24);

      if (step % 2 === 0) {
        const hi = ctx.createBufferSource();
        hi.buffer = this.noiseBuffer;
        const hp = ctx.createBiquadFilter();
        hp.type = 'highpass';
        hp.frequency.value = 6000;
        const hg = ctx.createGain();
        hg.gain.setValueAtTime(0.018, t0);
        hg.gain.exponentialRampToValueAtTime(0.0001, t0 + 0.05);
        hi.connect(hp);
        hp.connect(hg);
        hg.connect(this.music);
        hi.start(t0);
        hi.stop(t0 + 0.06);
      }

      if (step % 4 === 0) {
        const leadOsc = ctx.createOscillator();
        const lg = ctx.createGain();
        leadOsc.type = 'sine';
        leadOsc.frequency.value = root * 4 * 2 ** ((lead[step % 8]) / 12);
        lg.gain.setValueAtTime(0.0001, t0);
        lg.gain.exponentialRampToValueAtTime(0.025, t0 + 0.04);
        lg.gain.exponentialRampToValueAtTime(0.0001, t0 + 0.42);
        leadOsc.connect(lg);
        lg.connect(this.music);
        leadOsc.start(t0);
        leadOsc.stop(t0 + 0.44);
      }
      this.musicStep++;
    }, 200);
  }

  stopMusic() {
    this.musicOn = false;
    if (this.musicTimer) clearInterval(this.musicTimer);
    this.musicTimer = null;
  }
}

import * as THREE from 'three';
import { makeCanvasTexture, shortestDelta } from './utils.js';

function questionTexture() {
  return makeCanvasTexture(128, 128, (ctx, w, h) => {
    ctx.clearRect(0, 0, w, h);
    ctx.font = '900 94px "Arial Black", sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.lineWidth = 12;
    ctx.strokeStyle = 'rgba(35, 10, 60, .75)';
    ctx.strokeText('?', w / 2, h / 2 + 4);
    const g = ctx.createLinearGradient(0, 10, 0, h - 10);
    g.addColorStop(0, '#fff8d0');
    g.addColorStop(0.5, '#ffd166');
    g.addColorStop(1, '#ff5d9e');
    ctx.fillStyle = g;
    ctx.fillText('?', w / 2, h / 2 + 4);
  });
}

export class Pickups {
  constructor(scene, track) {
    this.scene = scene;
    this.track = track;
    this.group = new THREE.Group();
    scene.add(this.group);
    this.coins = [];
    this.boxes = [];
    this.time = 0;
    this._buildCoins();
    this._buildBoxes();
  }

  _buildCoins() {
    const gold = new THREE.MeshStandardMaterial({
      color: 0xffd166,
      emissive: 0xff9e2f,
      emissiveIntensity: 1.4,
      roughness: 0.2,
      metalness: 0.85,
    });
    const dark = new THREE.MeshStandardMaterial({
      color: 0x8c4a11,
      roughness: 0.35,
      metalness: 0.6,
    });
    const coinGeo = new THREE.TorusGeometry(0.52, 0.15, 8, 18);
    const discGeo = new THREE.CylinderGeometry(0.38, 0.38, 0.08, 16).rotateX(Math.PI / 2);
    const glowTex = makeCanvasTexture(128, 128, (ctx, w, h) => {
      const g = ctx.createRadialGradient(w / 2, h / 2, 0, w / 2, h / 2, w / 2);
      g.addColorStop(0, 'rgba(255,240,160,.95)');
      g.addColorStop(0.3, 'rgba(255,209,102,.55)');
      g.addColorStop(1, 'rgba(255,150,60,0)');
      ctx.fillStyle = g;
      ctx.fillRect(0, 0, w, h);
    });

    const rows = [
      [0.04, 0],
      [0.043, -4.4],
      [0.043, 4.4],
      [0.105, -4.2],
      [0.108, 0],
      [0.111, 4.2],
      [0.18, -2.6],
      [0.183, 2.6],
      [0.25, 0],
      [0.275, -4.5],
      [0.278, 4.5],
      [0.39, -3.2],
      [0.393, 3.2],
      [0.46, 0],
      [0.51, -4.3],
      [0.513, 4.3],
      [0.575, -2.2],
      [0.578, 2.2],
      [0.68, 0],
      [0.78, -4.2],
      [0.783, 4.2],
      [0.87, -2.6],
      [0.873, 2.6],
      [0.94, 0],
    ];

    for (const [u, lat] of rows) {
      const f = this.track.getFrame(u);
      const group = new THREE.Group();
      group.position.copy(f.pos).addScaledVector(f.right, lat).addScaledVector(f.up, 1.35);
      group.quaternion.copy(f.quat);
      const coin = new THREE.Mesh(coinGeo, gold);
      coin.castShadow = false;
      group.add(coin);
      const disc = new THREE.Mesh(discGeo, dark);
      group.add(disc);
      const glow = new THREE.Sprite(
        new THREE.SpriteMaterial({
          map: glowTex,
          transparent: true,
          opacity: 0.8,
          depthWrite: false,
          blending: THREE.AdditiveBlending,
          toneMapped: false,
        })
      );
      glow.scale.set(2.5, 2.5, 1);
      group.add(glow);
      this.group.add(group);
      this.coins.push({
        type: 'coin',
        u,
        lat,
        group,
        coin,
        glow,
        active: true,
        cooldown: 0,
        phase: Math.random() * 6,
        baseY: group.position.y,
      });
    }
  }

  _buildBoxes() {
    const tex = questionTexture();
    const glass = new THREE.MeshStandardMaterial({
      color: 0x8d68ff,
      emissive: 0x6d3cff,
      emissiveIntensity: 1.1,
      transparent: true,
      opacity: 0.26,
      roughness: 0.15,
      metalness: 0.6,
      depthWrite: false,
      side: THREE.DoubleSide,
    });
    const edgeMat = new THREE.LineBasicMaterial({ color: 0x9dfbff, transparent: true, opacity: 0.85, toneMapped: false });
    const coreMat = new THREE.MeshBasicMaterial({ color: 0xffd166, toneMapped: false });
    const cubeGeo = new THREE.BoxGeometry(2.0, 2.0, 2.0);
    const edgeGeo = new THREE.EdgesGeometry(cubeGeo);
    const coreGeo = new THREE.OctahedronGeometry(0.5, 0);

    const rows = [
      [0.095, -4.6],
      [0.095, 0],
      [0.095, 4.6],
      [0.455, -4.6],
      [0.455, 0],
      [0.455, 4.6],
      [0.79, -4.6],
      [0.79, 0],
      [0.79, 4.6],
    ];

    for (const [u, lat] of rows) {
      const f = this.track.getFrame(u);
      const group = new THREE.Group();
      group.position.copy(f.pos).addScaledVector(f.right, lat).addScaledVector(f.up, 1.6);
      group.quaternion.copy(f.quat);
      const cube = new THREE.Mesh(cubeGeo, glass);
      group.add(cube);
      const edges = new THREE.LineSegments(edgeGeo, edgeMat);
      group.add(edges);
      const core = new THREE.Mesh(coreGeo, coreMat);
      group.add(core);
      const sprite = new THREE.Sprite(
        new THREE.SpriteMaterial({
          map: tex,
          transparent: true,
          depthWrite: false,
          depthTest: true,
          toneMapped: false,
        })
      );
      sprite.scale.set(1.1, 1.1, 1);
      group.add(sprite);
      this.group.add(group);
      this.boxes.push({
        type: 'item',
        u,
        lat,
        group,
        cube,
        core,
        sprite,
        active: true,
        cooldown: 0,
        phase: Math.random() * 6,
        baseY: group.position.y,
      });
    }
  }

  update(dt, time) {
    this.time = time;
    for (const c of this.coins) {
      if (!c.active) {
        c.cooldown -= dt;
        if (c.cooldown <= 0) {
          c.active = true;
          c.group.visible = true;
        }
        continue;
      }
      c.coin.rotation.y += dt * 3.2;
      c.group.position.y = c.baseY + Math.sin(time * 2.6 + c.phase) * 0.16;
      c.glow.material.opacity = 0.6 + Math.sin(time * 5 + c.phase) * 0.18;
    }
    for (const b of this.boxes) {
      if (!b.active) {
        b.cooldown -= dt;
        if (b.cooldown <= 0) {
          b.active = true;
          b.group.visible = true;
        }
        continue;
      }
      b.group.rotation.y += dt * 0.9;
      b.core.rotation.y -= dt * 2.4;
      b.core.rotation.x += dt * 0.7;
      b.group.position.y = b.baseY + Math.sin(time * 1.8 + b.phase) * 0.18;
      const pulse = 1 + Math.sin(time * 3.5 + b.phase) * 0.035;
      b.cube.scale.setScalar(pulse);
      b.edges.scale.setScalar(pulse);
    }
  }

  check(racer) {
    const collected = [];
    for (const c of this.coins) {
      if (!c.active) continue;
      if (Math.abs(shortestDelta(racer.u, c.u)) < 0.0045 && Math.abs(racer.lateral - c.lat) < 2.1) {
        c.active = false;
        c.group.visible = false;
        c.cooldown = 10;
        collected.push(c);
      }
    }
    for (const b of this.boxes) {
      if (!b.active) continue;
      if (Math.abs(shortestDelta(racer.u, b.u)) < 0.0045 && Math.abs(racer.lateral - b.lat) < 2.1) {
        b.active = false;
        b.group.visible = false;
        b.cooldown = 6;
        collected.push(b);
      }
    }
    return collected;
  }

  reset() {
    for (const c of this.coins) {
      c.active = true;
      c.cooldown = 0;
      c.group.visible = true;
    }
    for (const b of this.boxes) {
      b.active = true;
      b.cooldown = 0;
      b.group.visible = true;
    }
  }
}

